  "overview": {
    "text": "Samuel Adams (1722–1803) was a Boston political organizer and Massachusetts Patriot whose work helped turn colonial opposition to British policies into a coordinated movement. He challenged Parliament’s authority to tax the colonies, wrote for newspapers, promoted boycotts, and helped organize Committees of Correspondence to connect resistance across communities. A leader associated with the Sons of Liberty, he chaired a Boston meeting on December 16, 1773, as colonists protested the Tea Act. Although Adams helped build support for resistance, the National Park Service reports no evidence that he joined the men who dumped tea from the ships. He later served in the Continental Congress, signed the Declaration of Independence, and became governor of Massachusetts.",
    "source_urls": [
      "https://www.nps.gov/articles/000/samuel-adams-boston-revolutionary.htm",
      "https://www.nps.gov/articles/000/boston-tea-party-in-real-time.htm",
      "https://history.house.gov/People/Detail/8317",
      "https://www.archives.gov/founding-docs/signers-factsheet"
    ]
  },
  "key_facts": [
    {
      "text": "Adams’s opposition to British taxation included organizing boycotts and writing political newspaper articles, sometimes under pen names.",
      "source_urls": [
        "https://www.nps.gov/articles/000/samuel-adams-boston-revolutionary.htm"
      ]
    },
    {
      "text": "He helped establish Committees of Correspondence, which connected communities and supported coordinated resistance.",
      "source_urls": [
        "https://www.nps.gov/articles/000/samuel-adams-boston-revolutionary.htm"
      ]
    },
    {
      "text": "On December 16, 1773, Adams chaired a meeting about the tea crisis; the National Park Service says there is no evidence he took part in the tea’s destruction.",
      "source_urls": [
        "https://www.nps.gov/articles/000/samuel-adams-boston-revolutionary.htm"
      ]
    },
    {
      "text": "He represented Massachusetts in the First and Second Continental Congresses and signed the Declaration of Independence.",
      "source_urls": [
        "https://history.house.gov/People/Detail/8317",
        "https://www.archives.gov/founding-docs/signers-factsheet"
      ]
    },
    {
      "text": "After the Revolution, Adams served as lieutenant governor and governor of Massachusetts.",
      "source_urls": [
        "https://history.house.gov/People/Detail/8317"
      ]
    }
  ],
